<?php require_once __DIR__.'/_base.php'; $title='Rate Booking'; include __DIR__.'/../includes/header.php'; ?><div class="dashboard-shell"><?php include __DIR__.'/../includes/sidebar.php'; ?><section class="content-area"><?php $bid=(int)($_GET['booking']??$_POST['booking_id']??0);$st=$pdo->prepare("SELECT b.*,p.name provider_name,s.service_name FROM bookings b JOIN providers p ON p.id=b.provider_id JOIN services s ON s.id=b.service_id WHERE b.id=? AND b.user_id=? AND b.status='Completed'");$st->execute([$bid,$u['id']]);$b=$st->fetch();if(!$b){echo '<div class="alert alert-danger">Only your completed bookings can be rated.</div>';return;}$chk=$pdo->prepare('SELECT id FROM ratings WHERE booking_id=?');$chk->execute([$bid]);if($chk->fetch()){echo '<div class="alert alert-info">This booking has already been rated.</div>';return;}if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$r=(int)$_POST['rating'];if($r>=1&&$r<=5){$pdo->prepare('INSERT INTO ratings(booking_id,user_id,provider_id,rating,review) VALUES(?,?,?,?,?)')->execute([$bid,$u['id'],$b['provider_id'],$r,post('review')]);flash('success','Thank you for your feedback.');redirect('bookings.php');}}?><div class="service-card p-4 col-lg-7"><h3>Rate <?=e($b['provider_name'])?></h3><p class="text-secondary"><?=e($b['service_name'])?> · Booking #<?=$bid?></p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label class="form-label">Rating</label><select name="rating" class="form-select mb-3" required><option value="5">5 — Excellent</option><option value="4">4 — Good</option><option value="3">3 — Okay</option><option value="2">2 — Poor</option><option value="1">1 — Very poor</option></select><label class="form-label">Review</label><textarea name="review" class="form-control mb-3" rows="5"></textarea><button class="btn btn-success">Submit Review</button></form></div></section></div><?php include __DIR__.'/../includes/footer.php'; ?>